SELECT 'core-2026-09-v4','prepositions-of-place','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"prepositions-of-place","title":"Prepositions of place","level":"A1","order":18,"summary":"Use in for containment, on for surfaces, and at for activity locations and points.","learningGoals":["Inside a space","On a surface","At a point or activity"],"guidance":"Read the rules and examples, then try a 20-question session. Explain why your chosen form fits the context and revisit any missed skill.","rules":[{"title":"Inside a space","explanation":"In locates something within a container, area, city or country. Read the stated physical relation carefully.","examples":["The tools are in a chest.","The village is in a valley."]},{"title":"On a surface","explanation":"On describes contact with a surface, including vertical surfaces. It does not simply mean higher than something.","examples":["The chart is on the wall.","The cloth is on the counter."]},{"title":"At a point or activity","explanation":"At often marks an exact point or an activity location. Expressions such as at home and at work are conventional. Some places allow different prepositions with different meanings; each question specifies its intended meaning.","examples":["Meet me at the entrance.","She is at work."]}],"tips":["Check both the meaning and the form before answering.","Use the explanation to understand a mistake before moving on.","A practice result is feedback, not an official language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v2","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-prepositions-of-place"],"assessment":"Practice only; approximate teaching labels, not validated CEFR assessment."},"chapter":{"introduction":["Place prepositions describe a relation, not a permanent property of a location. The same place can be presented as a container, a surface or a point in a route. The prompt’s intended relation is therefore essential; a dictionary list of place names alone is not enough."],"rules":[{"title":"Inside a space","explanation":"In locates something within a container, area, city or country. Read the stated physical relation carefully.","examples":["The tools are in a chest.","The village is in a valley.","The picture is **on** the wall."],"pattern":"**in** a room / **in** a city","paragraphs":["In commonly presents a place as an enclosing space or an area within boundaries. A person can be in a room or in a country. The enclosure need not be a physical box. Into instead highlights movement from outside to inside; it is not the ordinary static counterpart of in."],"id":"prepositions-of-place-foundation-1","domain":"prepositions","referenceIds":["bc-prepositions-of-place"],"readingVersion":"foundations-2026-09-v2"},{"title":"On a surface","explanation":"On describes contact with a surface, including vertical surfaces. It does not simply mean higher than something.","examples":["The chart is on the wall.","The cloth is on the counter.","The keys are **in** the drawer."],"pattern":"**on** a shelf / **on** the ceiling","paragraphs":["On commonly describes contact with a surface, even a vertical or overhead one: on the wall, on the ceiling. It also appears in conventional phrases such as on a bus. Surface contact is a useful core meaning, but not every use is literal."],"id":"prepositions-of-place-foundation-2","domain":"prepositions","referenceIds":["bc-prepositions-of-place"],"readingVersion":"foundations-2026-09-v2"},{"title":"At a point or activity","explanation":"At often marks an exact point or an activity location. Expressions such as at home and at work are conventional. Some places allow different prepositions with different meanings; each question specifies its intended meaning.","examples":["Meet me at the entrance.","She is at work.","Meet me **at** the ticket barrier."],"pattern":"**at** the entrance / **at** work","paragraphs":["At often presents a location as a point, meeting place or conventional activity location. At school can mean attending school; in the school foregrounds being inside the building. At the desk does not mean standing on its surface."],"id":"prepositions-of-place-foundation-3","domain":"prepositions","referenceIds":["bc-prepositions-of-place"],"readingVersion":"foundations-2026-09-v2"},{"title":"Contrasts and edge cases","explanation":"Go to gives a destination, go into gives entry and come out of gives exit. Across goes from one side to another, through follows an interior passage, and along follows a length. Home often works without to after go. Prepositions vary with conventional usage and sometimes with national variety.","examples":["The picture is **on** the wall.","The keys are **in** the drawer.","Meet me **at** the ticket barrier."],"id":"prepositions-of-place-foundation-4","domain":"prepositions","referenceIds":["bc-prepositions-of-place"],"readingVersion":"foundations-2026-09-v2"},{"domain":"prepositions","id":"preposition-complements","title":"Prepositions with nouns, pronouns and clauses","explanation":"A preposition can take a noun phrase, an object pronoun or an -ing clause as its complement. Some also take an embedded interrogative clause. A preposition phrase can function as a complement or a modifier. A familiar word such as to can instead be an infinitive marker in another construction.","pattern":"after **lunch** / after **leaving**","examples":["She is interested **in how it works**.","I look forward **to meeting** you."],"commonMistakes":["Distinguish preposition to from infinitival to: look forward to meeting uses a preposition, while hope to meet uses an infinitive marker."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["**in** a room / **in** a city","**on** a shelf / **on** the ceiling","**at** the entrance / **at** work"],"readingVersion":"core-2026-09-v4"},"stage":"2 · Everyday descriptions","prerequisites":["prepositions-of-time"],"readingReferenceIds":["bc-prepositions-of-place","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='prepositions-of-place'
